_UMR = [("Dati, tumutugtog ako ng piano at saxophone.", "In the past, I played the piano and saxophone."), ("Ngayon, nakikinig na lang ako ng musika, nagbabasa ng diyaryo o libro, at nanonood ng balita.", "Now I just listen to music, read the newspaper or books and watch the news."), ("Hindi na po kayo nagpa-piano at nagsa-saxophone?", "You no longer play the piano or the saxophone?"), ("Napapagod na ako.", "I am already getting tired."), ("Paminsan-minsan, nagmamadyong at nagbabaraha kami.", "From time to time, we play mahjong and cards."), ("Gustung-gusto kong lumangoy sa ilog.", "I like to swim in the river very much."), ("Nag-aalaga din ako ng hayop at nagtatanim ng halaman.", "I also take care of animals and grow plants."), ("Mahilig ka palang maggantsilyo?", "So you are fond of crocheting?"), ("Si Nanay ang nagturo sa akin.", "Mother was the one who taught me."), ("Marunong ka bang magbisikleta?", "Do you know how to ride a bike?"), ("Interesado akong matuto.", "I am interested in learning."), ("Turuan mo naman akong magbisikleta.", "Teach me how to ride a bike, please.")]
_CONJ = [("tumugtog", "tumugtog", "tumutugtog", "tutugtog"), ("magbasa", "nagbasa", "nagbabasa", "magbabasa"), ("magpiyano", "nagpiyano", "nagpipiyano", "magpipiyano"), ("magbaraha", "nagbaraha", "nagbabaraha", "magbabaraha"), ("mag-alaga", "nag-alaga", "nag-aalaga", "mag-aalaga"), ("makinig", "nakinig", "nakikinig", "makikinig"), ("mapagod", "napagod", "napapagod", "mapapagod"), ("matuto", "natuto", "natututo", "matututo"), ("masanay", "nasanay", "nasasanay", "masasanay"), ("maggantsilyo", "naggantsilyo", "naggagantsilyo", "maggagantsilyo"), ("magbisikleta", "nagbisikleta", "nagbibisikleta", "magbibisikleta")]
