        card("Ma verb conjugation", "Ma verbs are conjugated like mag verbs. Past tense: change ma to na. Present: keep na and reduplicate the first syllable of the root. Future: ma plus the first syllable of the root repeated plus the root.", tables=[table(["Root", "Meaning", "Infinitive", "Past", "Present", "Future"], [list(r) for r in _MAR], say=[0, 2, 3, 4, 5])]),
